#!/usr/bin/env bash
# Remove generated/stale artifacts left behind by past `cdk synth`/`cdk deploy`
# runs in this directory. Everything removed here is fully regenerated by the
# next `cdk synth`/`cdk deploy` -- none of it is source.
#
# Usage: ./clean_deploy_artifacts.sh
set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")"

# Synthesized CloudFormation output (template/manifest/tree/metadata). Can go
# stale after renaming the stack or any resource within it (old files for the
# previous stack name/id linger until manually removed -- `cdk synth` never
# deletes them on its own).
if [ -d cdk.out ]; then
   echo "Removing cdk.out/"
   rm -rf cdk.out
fi

# Free-form deploy session logs from past `cdk deploy`/`cdk diff` runs
# (manually captured, not written by any CDK tooling convention -- naming
# varies run to run).
shopt -s nullglob
for f in deploylog.txt updatelog_*.txt output.txt; do
   if [ -e "$f" ]; then
      echo "Removing $f"
      rm -f "$f"
   fi
done

echo "Done."
